// === Tab: mySketch ===
//
// Submitted to curation
//  "Show Your Work" (Improve some of your earliest creative coding) 👀 #WCCChallenge
//
// This is a rewrite of an earlier IFS (iterated function system) rendering sketch,
// but this time I use the very powerful webgl2 transform feedback feature in 
// order to compute the transformation of thousands of points very quickly.
//


let init, render, gl;
let {
	mat3,
	mat4
} = glMatrix;

function setup() {
	const cnv = createCanvas(windowWidth, windowHeight, WEBGL);
	gl = drawingContext;
	let pd = pixelDensity();

	const numParticles = 400000;
	const createPoints = (num, ranges) =>
		new Array(num).fill(0).map(_ => ranges.map(range => random(...range))).flat();
	const positions = new Float32Array(createPoints(numParticles, [
		[pd],
		[pd],
		[0, 0]
	]));

	({
		init,
		render
	} = transformFeedback(gl));
	init(positions);
	setScheme('color');
}

function mousePressed () {
	let schemes = ['color', 'bw', 'wb'];
	let i = schemes.indexOf(scheme);
	setScheme (schemes[(i+1)%schemes.length]);
}

function transfMult(...transfs) {
	let result = transfs[0];
	for (let i = 1; i < transfs.length; i++) {
		let t = transfs[i];
		mat3.mul(result, result, t)
	}
	return result;
}

const TR = (vec) => mat3.fromTranslation([], vec);
const SC = (vec) => mat3.fromScaling([], vec);
const ROT = (ang) => mat3.fromRotation([], ang);
const PRJ = (minx, maxx, miny, maxy) => {
	let extra = (width - height) / height / 2 * (maxx - minx);
	return mat4.ortho([], minx - extra, maxx + extra, miny, maxy, -1, 1);
}

let palette, bkg, scheme;

function setScheme(s) {
	scheme = s;
	if (s == 'color') {
		let a = 0.5;
		palette = [
			[1, 0, 0, a],
			[0, 1, 0, a],
			[0, 0, 1, a],
			[1, 1, 0, a],
			[1, 0, 1, a],
			[0, 1, 1, a],
			[1, 0.5, 0.5, a],
			[0.5, 0.5, 1, a],
			[0.5, 1, 0.5, a],
		].flat();
		gl.enable (gl.BLEND);
		gl.blendFunc (gl.SRC_ALPHA, gl.ONE);
		bkg = color('black')
	} else if (s == 'wb') {
		palette = new Array(9).fill([1, 1, 1, 0.5]).flat();
		bkg = color('black')
		gl.enable (gl.BLEND);
		gl.blendFunc (gl.SRC_ALPHA, gl.ONE);
	} else if (s == 'bw') {
		palette = new Array(9).fill([0.0,0.0,0.0, 1]).flat();
		bkg = color('white')
		gl.disable (gl.BLEND);
	}
}

function draw() {
	var t = millis() * 0.0005; // seconds
	let x = (sin(t) + 1) * 0.25;
	let ar = width / height;
	let transf, projection;
	switch (int(millis() / 15000) % 6) {
		case 0:
			transf = [
				...transfMult(
					mat3.fromValues(1 / 2, 1 / 2, 0, -1 / 2, 1 / 2, 0, 0, 0, 1),
					ROT(t / 2)),
				...transfMult(
					mat3.fromValues(1 / 2, -1 / 2, 0, 1 / 2, 1 / 2, 0, 1 / 2, 1 / 2, 1),
					ROT(-t / 2)),
			];
			projection = PRJ(-1.7, 2.2, -1.6, 1.6);
			break;

		case 1:
			// Heighway dragon
			transf = [
				...transfMult(
					mat3.fromValues(1 / 2, 1 / 2, 0, -1 / 2, 1 / 2, 0, 0, 0, 1),
					ROT(-t / 2)),
				...transfMult(
					mat3.fromValues(-1 / 2, 1 / 2, 0, -1 / 2, -1 / 2, 0, 1, 0, 1),
					ROT(t / 2)),
			];
			projection = PRJ(-1.7, 2.2, -1.6, 1.6);
			break;
		case 3: // Tree
			transf = [
				...SC([0.05, 0.6]),
				...transfMult(TR([0, 1]), SC([0.05, -0.5], ROT(t))),
				...transfMult(
					mat3.fromValues(0.46, 0.39, 0, -0.32, 0.38, 0, 0, 0.6, 1),
					ROT(t)),
				...transfMult(
					mat3.fromValues(0.47, 0.17, 0, -0.15, 0.42, 0, 0, 1.1, 1),
					ROT(-t)),
				...transfMult(
					mat3.fromValues(0.43, -0.25, 0, 0.28, 0.45, 0, 0, 1, 1),
					ROT(t)),
				...transfMult(
					mat3.fromValues(0.42, -0.35, 0, 0.26, 0.31, 0, 0, 0.7, 1),
					ROT(-t)),
			];
			projection = PRJ(-1, 1, -0.2, 2.2);
			break;
		case 4: // Sierpinski gasket
			transf = [
				...transfMult(TR([0.5, 0]),
					SC([0.5, 0.5]),
					TR([0.5, 0.5]),
					ROT(t),
					TR([-0.5, -0.5])
				),
				...transfMult(TR([0.25, 0.5]),
					SC([0.5, 0.5]),
					TR([0.5, 0.5]),
					ROT(-t * 0.5),
					TR([-0.5, -0.5])
				),
				...transfMult(TR([0.0, 0.0]),
					SC([0.5, 0.5]),
					TR([0.5, 0.5]),
					ROT(t),
					TR([-0.5, -0.5])
				)
			];
			projection = PRJ(-0.2, 1.2, -0.1, 1.1);
			break;
		case 5: // McWorter Pentigree
			transf = [...transfMult(ROT(radians(36) + t * 0.3), SC([0.381966, 0.381966])),
				...transfMult(TR([0.309, 0.225 + x]), ROT(radians(108) - t), SC([0.381966, 0.381966])),
				...transfMult(TR([0.191 - x, 0.588]), ROT(radians(-36) + t), SC([0.381966, 0.381966])),
				...transfMult(TR([0.500 + x, 0.363 - x]), ROT(radians(-108 - t)), SC([0.381966, 0.381966])),
				...transfMult(TR([0.382, x]), ROT(radians(-36 - t)), SC([0.381966, 0.381966])),
				...transfMult(TR([0.691 + x, -0.225]), ROT(radians(36 + t)), SC([0.381966, 0.381966])),
			];
			projection = PRJ(-0.8, 1.8, -0.8, 1.5);
			break;
		case 2: // Sierpinksi carpet
			transf = [
				...transfMult(TR([-1 / 3, -1 / 3 + x]), SC([1 / 3, 1 / 3]), ROT(t)),
				...transfMult(TR([-1 / 3, +1 / 3 - x]), SC([1 / 3, 1 / 3]), ROT(-t)),
				...transfMult(TR([+1 / 3, +1 / 3 + x]), SC([1 / 3, 1 / 3]), ROT(t)),
				...transfMult(TR([+1 / 3, -1 / 3 - x]), SC([1 / 3, 1 / 3]), ROT(-t)),

				...transfMult(TR([-1 / 3 - x, 0]), SC([1 / 3, 1 / 3])),
				...transfMult(TR([+1 / 3 + x, 0]), SC([1 / 3, 1 / 3])),
				...transfMult(TR([-x, -1 / 3]), SC([1 / 3, 1 / 3])),
				...transfMult(TR([+x, +1 / 3]), SC([1 / 3, 1 / 3])),
			];
			projection = PRJ(-1.1, 1.1, -1.1, 1.1);
			break;
	}
	resetShader();
	background (bkg)
	render(transf, projection, palette);

}

// === Tab: TF4 ===
//
// From https://webgl2fundamentals.org/webgl/lessons/webgl-gpgpu.html
//
function transformFeedback(gl) {

	/**
	* Shader Sources
	**/

	const ntransfDef = "\n#define max_ntransf 10\n";
	const updatePositionVS = `#version 300 es
			${ntransfDef}
			in vec3 oldPosition;
			uniform int ntransf;
			uniform mat3 transf[max_ntransf];
			uniform vec2 canvasDimensions;

			out vec3 newPosition;

			float random (vec2 st) {
				return fract(sin(dot(st.xy, vec2(12.9898,78.233))) * 43758.5453123);
			}

			void main() {
			  int i = int(random(oldPosition.xy)*float(ntransf));
				newPosition = vec3((transf[i] * vec3(oldPosition.xy,1)).xy,float(i));
			}
			`;

	const updatePositionFS = `#version 300 es
			precision highp float;
			void main() {
			}
			`;

	const drawParticlesVS = `#version 300 es
			in vec4 position;
			uniform mat4 matrix;
			out float id;

			void main() {
				// do the common matrix math
				vec4 p = matrix * vec4(position.xy, 0., 1.);
				// Pass the z coordinate as id
				gl_Position = p;
				id = position.z;
				gl_PointSize = 5.0;
			}
			`;

	const drawParticlesFS = `#version 300 es
			precision highp float;
			${ntransfDef}
			out vec4 outColor;
			uniform vec4 palette[max_ntransf];
			in float id;
			void main() {
				if (dot(gl_PointCoord-0.5,gl_PointCoord-0.5)>0.25) discard; 
				else outColor = palette[int(id)];
			}
 	 `;

	/**
	 * Utilities
	 **/ 

	function createShader(gl, type, src) {
		const shader = gl.createShader(type);
		gl.shaderSource(shader, src);
		gl.compileShader(shader);
		if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
			throw new Error(gl.getShaderInfoLog(shader));
		}
		return shader;
	}

	function createProgram(gl, shaderSources, transformFeedbackVaryings) {
		const program = gl.createProgram();
		[gl.VERTEX_SHADER, gl.FRAGMENT_SHADER].forEach((type, ndx) => {
			var shader = createShader(gl, type, shaderSources[ndx]);
			gl.attachShader(program, shader);
		});
		if (transformFeedbackVaryings) {
			gl.transformFeedbackVaryings(
				program,
				transformFeedbackVaryings,
				gl.SEPARATE_ATTRIBS,
			);
		}
		gl.linkProgram(program);
		if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
			throw new Error(gl.getProgramParameter(program));
		}
		return program;
	}

	function setBuffer(gl, buf, sizeOrData, usage) {
		gl.bindBuffer(gl.ARRAY_BUFFER, buf);
		gl.bufferData(gl.ARRAY_BUFFER, sizeOrData, usage);
		return buf;
	}

	function makeVertexArray(gl, bufLocPairs) {
		const va = gl.createVertexArray();
		gl.bindVertexArray(va);
		for (const [buffer, loc] of bufLocPairs) {
			gl.bindBuffer(gl.ARRAY_BUFFER, buffer);
			gl.enableVertexAttribArray(loc);
			gl.vertexAttribPointer(
				loc, // attribute location
				3, // number of elements
				gl.FLOAT, // type of data
				false, // normalize
				0, // stride (0 = auto)
				0, // offset
			);
		}
		return va;
	}

	/**
	*  Setup
	**/

	const updatePositionProgram = createProgram(
		gl, [updatePositionVS, updatePositionFS], ['newPosition']);
	const drawParticlesProgram = createProgram(
		gl, [drawParticlesVS, drawParticlesFS]);

	const updatePositionPrgLocs = {
		oldPosition: gl.getAttribLocation(updatePositionProgram, 'oldPosition'),
		ntransf: gl.getUniformLocation(updatePositionProgram, 'ntransf'),
		transf: gl.getUniformLocation(updatePositionProgram, 'transf'),
		canvasDimensions: gl.getUniformLocation(updatePositionProgram, 'canvasDimensions'),
	};

	const drawParticlesProgLocs = {
		position: gl.getAttribLocation(drawParticlesProgram, 'position'),
		matrix: gl.getUniformLocation(drawParticlesProgram, 'matrix'),
		palette: gl.getUniformLocation(drawParticlesProgram, 'palette'),
	};


	const position1Buffer = gl.createBuffer();
	const position2Buffer = gl.createBuffer();

	const updatePositionVA1 = makeVertexArray(gl, [
		[position1Buffer, updatePositionPrgLocs.oldPosition],
	]);
	const updatePositionVA2 = makeVertexArray(gl, [
		[position2Buffer, updatePositionPrgLocs.oldPosition],
	]);

	const drawVA1 = makeVertexArray(
		gl, [
			[position1Buffer, drawParticlesProgLocs.position]
		]);
	const drawVA2 = makeVertexArray(
		gl, [
			[position2Buffer, drawParticlesProgLocs.position]
		]);

	function setTransformFeedback(gl, tf, buffer) {
		gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, tf);
		gl.bindBufferBase(gl.TRANSFORM_FEEDBACK_BUFFER, 0, buffer);


		return tf;
	}

	const tf1 = gl.createTransformFeedback();
	const tf2 = gl.createTransformFeedback();

	var numParticles;

	function init (positions) {
		numParticles = positions.length/3;

		setBuffer(gl, position1Buffer, positions, gl.DYNAMIC_DRAW);
		setTransformFeedback (gl, tf1, position1Buffer);

		setBuffer(gl, position2Buffer, positions, gl.DYNAMIC_DRAW);
		setTransformFeedback (gl, tf2, position2Buffer);

		// unbind left over stuff
		gl.bindBuffer(gl.ARRAY_BUFFER, null);
		gl.bindBuffer(gl.TRANSFORM_FEEDBACK_BUFFER, null);

	}



	let current = {
		updateVA: updatePositionVA1, // read from position1
		tf: tf2, // write to position2
		drawVA: drawVA2, // draw with position2
	};
	let next = {
		updateVA: updatePositionVA2, // read from position2
		tf: tf1, // write to position1
		drawVA: drawVA1, // draw with position1
	};

	function render(transf, projection, palette) {

		// gl.clearColor(0,0,0,1);
		// gl.clear(gl.COLOR_BUFFER_BIT);

		// compute the new positions
		gl.useProgram(updatePositionProgram);
		gl.bindVertexArray(current.updateVA);
		gl.uniform2f(updatePositionPrgLocs.canvasDimensions, gl.canvas.width, gl.canvas.height);
		gl.uniform1i(updatePositionPrgLocs.ntransf,int(transf.length/9))
		gl.uniformMatrix3fv(updatePositionPrgLocs.transf, false, transf);

		gl.enable(gl.RASTERIZER_DISCARD);

		gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, current.tf);
		gl.beginTransformFeedback(gl.POINTS);
		gl.drawArrays(gl.POINTS, 0, numParticles);
		gl.endTransformFeedback();
		gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, null);

		// turn on using fragment shaders again
		gl.disable(gl.RASTERIZER_DISCARD);

		// now draw the particles.
		gl.useProgram(drawParticlesProgram);


		gl.bindVertexArray(current.drawVA);
		gl.viewport(0, 0, gl.canvas.width, gl.canvas.height);
		gl.uniformMatrix4fv(
			drawParticlesProgLocs.matrix,
			false,
			projection,
		);
		gl.uniform4fv(drawParticlesProgLocs.palette,palette);
		gl.drawArrays(gl.POINTS, 0, numParticles);

		// swap which buffer we will read from
		// and which one we will write to
		[current,next] = [next, current]
		// {
		// 	const temp = current;
		// 	current = next;
		// 	next = temp;
		// }
	}

	return {init,render};

}

